-- Fork migration 127: the Consumables module (tubes, tips, plates, gloves...), made like Reagents, for the teams that have modules already
-- (a team with none gets it with the default modules). A team that has a module called Consumables is left alone.
INSERT INTO `inventory_categories` (`team`, `title`, `color`, `is_private`, `ordering`, `state`, `fields`, `settings`)
    SELECT t.`id`, 'Consumables', '4f9da6', 0, 7, 1, '{"extra_fields": {"Consumable type": {"type": "select", "value": "", "options": ["Tubes", "Tips", "Plates", "Gloves", "Filters", "Syringes", "Needles", "Wipes", "Other"], "position": 1}, "Supplier": {"type": "text", "value": "", "position": 2}, "Catalog number": {"type": "text", "value": "", "position": 3}, "Lot number": {"type": "text", "value": "", "position": 4}, "Pack size": {"type": "text", "value": "", "position": 5}, "Expiry date": {"type": "date", "value": "", "position": 6}, "Storage conditions": {"type": "text", "value": "", "position": 7}, "Link": {"type": "url", "value": "", "position": 100}}}', '{"columns": [{"key": "field:Consumable type", "label": "Type"}, {"key": "field:Supplier", "label": "Supplier"}, {"key": "field:Catalog", "label": "Catalog no."}, {"key": "field:Lot", "label": "Lot"}, {"key": "field:Pack size", "label": "Pack size"}, {"key": "field:Expiry", "label": "Expiry"}, {"key": "quantity", "label": "Quantity"}, {"key": "owner", "label": "Owner"}], "sequence_field": null, "requires_sequence_file": false}'
    FROM `teams` AS t
    WHERE EXISTS (SELECT 1 FROM `inventory_categories` AS c WHERE c.`team` = t.`id`)
        AND NOT EXISTS (SELECT 1 FROM `inventory_categories` AS c WHERE c.`team` = t.`id` AND c.`title` = 'Consumables');
